def[predicateDisplay](
    Algebra.Monoid(G@Algebra.ctxt.G, $\cdot$@Algebra.ctxt.mul),
    struct[enumerate](
        member[colon](
            %Associativity%,
            Logic.forall-typed[paren](
                list-partial(@x, @y, @z),
                G@Algebra.ctxt.G,
                Eq(
                    Bop.apply($\cdot$@Algebra.ctxt.mul, Bop.apply[paren]($\cdot$@Algebra.ctxt.mul, x, y), z),
                    Bop.apply($\cdot$@Algebra.ctxt.mul, x, Bop.apply[paren]($\cdot$@Algebra.ctxt.mul, y, z))
                )
            )
        ),
        member[colon](
            %Identity%,
            Logic.exists-typed(
                @e,
                G@Algebra.ctxt.G,
                Logic.forall-typed(
                    @a,
                    G@Algebra.ctxt.G,
                    Logic.and(Eq(Bop.apply($\cdot$@Algebra.ctxt.mul, e, a), a), Eq(Bop.apply($\cdot$@Algebra.ctxt.mul, a, e), a))
                )
            )
        )
    )
)
